contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Drive c: call lockInGuess with a provided value and assert the contract's balance changed by that value.
    // This captures that in P lockInGuess requires msg.value == 1 ether (so arbitrary value cannot be sent),
    // while M allows arbitrary msg.value so the contract balance reflects the sent amount.
    function run(bytes32 hash, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient test balance");

        uint256 before = address(c).balance;

        // state-changing call must be top-level
        c.lockInGuess{value: sendAmount}(hash);

        uint256 after = address(c).balance;

        // The distinguishing rule: the contract balance increases exactly by sendAmount.
        // On P this holds only when sendAmount == 1 ether (so for arbitrary sendAmount it does NOT hold),
        // but on M it will hold for any sendAmount. We assert the general relation.
        assert(after - before == sendAmount);
    }

    // allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // amount is value sent to lockInGuess; any caller address is represented by msg.sender here
    function run(uint256 amount, bytes32 hash) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        // call lockInGuess with provided value
        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        // On the original contract, reverted is true iff amount != 1 ether.
        // Express that rule: reverted == (amount != 1 ether)
        assert(reverted == (amount != 1 ether));
    }
    receive() external payable {}
}

