contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: attempts to create a new guess from this contract
    // params: hash to lock, and amount of wei to send (should be 1 ether)
    function run(bytes32 hash, uint256 pay) public payable {
        // ensure this contract has enough balance to send to c
        require(address(this).balance >= pay);
        // precondition: ensure no existing guess for this test caller (this contract)
        // we read the public mapping via autogenerated getter: guesses(address) returns (uint256 block, bytes32 guess)
        // note: the getter is guesses(address) returning (uint, bytes32)
        (uint256 beforeBlock, ) = c.guesses(address(this));
        require(beforeBlock == 0);

        // perform the state-changing call that should create a new guess on the original contract
        c.lockInGuess{value: pay}(hash);

        // observe the stored block for this address after the call
        (uint256 afterBlock, bytes32 storedGuess) = c.guesses(address(this));

        // The distinguishing property: after a successful lockInGuess with 1 ether, a new future_block is stored equal to current block+1
        // We cannot read block.number inside c, but afterBlock should be > 0 and equal to the block when it was set (we assert it's exactly one greater than the call block by comparing relative ordering)
        // For a machine-checkable simple rule, assert that when pay == 1 ether then afterBlock > block.number - 1 and storedGuess == hash
        // This captures that a new guess was created and stored correctly. The mutant that disallows creating when none existed will fail this.
        assert(pay == 1 ether ? (afterBlock != 0 && storedGuess == hash) : true);
    }

    // allow receiving ether so the test harness can fund this contract
    receive() external payable {}
}

