contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 h, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount);

        // attempt the call and record whether it reverted
        bool reverted;
        try c.lockInGuess{value: amount}(h) { reverted = false; } catch { reverted = true; }

        // The property: lockInGuess with exactly 1 ether should revert exactly when the caller already has a guess.
        // We cannot read internal guesses, so we express the rule using two attempts:
        // If the first attempt reverted, then a subsequent attempt should NOT succeed in creating a new guess
        // unless the contract behaved like the mutant. Instead, we use the following observable equivalent:
        // - If the first call reverted, then calling again with 1 ether should also revert (since original requires no prior guess,
        //   and mutant would allow only when guess exists). Conversely, if the first call succeeded, a second call must revert
        //   because original prevents creating another guess while one exists.
        // So reverted must equal (secondAttemptReverted).

        bool reverted2;
        try c.lockInGuess{value: amount}(h) { reverted2 = false; } catch { reverted2 = true; }

        assert(reverted == reverted2);
    }
    receive() external payable {}
}

