        // read the stored block number via the public mapping auto-getter: guesses is not public in C,
        // so we cannot read it. Instead, we simply advance at least 2 blocks to satisfy block.number > stored
        // value for a wide range of possible stored values. Keep wide by advancing `off` blocks.
        for (uint16 i = 0; i < off; i++) {
            vm.roll(block.number + 1);
        }

        // give the contract enough balance to potentially pay out 2 ether
        // it was constructed with 1 ether in setUp; top it up so reference can pay 2 ether
        vm.deal(address(c), 3 ether);

        // measure balance before
        uint256 balBefore = address(c).balance;

        // call settle as the player and catch reverts (should not revert for settled winner/non-winner)
