        // successfully and the contract lost exactly 2 ether, that matches the reference rule. We assert that
        // either settle reverted (ok == false) or, if it succeeded, the balance decreased by a multiple of 2 ether
        // (i.e., not by exactly 1 ether). This will hold for the reference but fail on the mutant for some inputs.

        // compute delta (use signed arithmetic carefully)
        uint256 delta;
        if (balBefore >= balAfter) {
            delta = balBefore - balAfter;
        } else {
            delta = 0;
        }

