import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // General rule: after a successful winning settle() call, the contract's balance decreases by exactly 2 ether
    // We fuzz the actor and the block offset to create admissible scenarios; we deploy a helper that will accept
    // transfers (an EOA would also accept, but we need to fund and act as a distinct address), and we let the
    // fuzzer find cases where the mutant (which pays 1 ether) deviates.
    function testFuzz_property(address player, uint256 blockOffset) public {
        // keep player non-zero and distinct from this contract
        vm.assume(player != address(0));
        vm.assume(player != address(this));
        // bound block offset to a reasonable range so block.number + offset fits and we can advance
        uint256 off = bound(blockOffset, 1, 50);

        // fund the player so they can lock in a guess
        vm.deal(player, 2 ether);

        // player locks a guess by sending 1 ether
        bytes32 guess = keccak256(abi.encodePacked("guess"));
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // advance to the locked block
        uint256 targetBlock = block.number + 1;
        // move forward additional off blocks so settle condition (block.number > locked block) holds
        vm.roll(targetBlock + off);

        // ensure contract has 2 ether so reference can pay out 2 ether on win
        // top up contract if needed
        if (address(c).balance < 2 ether) {
            vm.deal(address(this), 2 ether);
            payable(address(c)).transfer(2 ether);
        }

        // To make the guess succeed we need the expected answer; compute using the same logic as C
        bytes32 answer = keccak256(abi.encodePacked(blockhash(targetBlock)));
        // overwrite stored guess to match answer by calling lockInGuess anew isn't possible because lock-in allowed only when guesses[msg.sender].block == 0.
        // Instead, we performed lockInGuess earlier with hash("guess"). To force a winning path deterministically, we will
        // directly set up a new player who will lock the correct guess. Use a fresh addr2.
        address player2 = address(uint160(uint256(keccak256(abi.encodePacked(player, block.number)))));
        vm.deal(player2, 2 ether);
        vm.prank(player2);
        c.lockInGuess{value: 1 ether}(answer);
        // advance to its locked block (which will be current block + 1)
        uint256 lockedBlock = block.number + 1;
        vm.roll(lockedBlock + 1);

        // Ensure contract has sufficient balance (>=2 ether)
        if (address(c).balance < 2 ether) {
            vm.deal(address(this), 2 ether);
            payable(address(c)).transfer(2 ether);
        }

        uint256 before = address(c).balance;

        // call settle from player2; capture whether it succeeds (should) and then check balance delta
        vm.prank(player2);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // If settle succeeded, reference C always reduces balance by exactly 2 ether for a winning guess.
        // The mutant that pays 1 ether will make this assertion fail for some fuzzed inputs.
        if (ok) {
            uint256 after = address(c).balance;
            assertTrue(before - after == 2 ether);
        } else {
            // If settle reverted, still assert a true condition that must hold for reference: settle should not revert here.
            // This branch should not happen on the correct contract for these admissible inputs; force failure if it does.
            assertTrue(false);
        }
    }
}

